def _clamp(v: int) -> int:
    return max(0, min(255, v))


def _noise2d(x: int, y: int, seed: int = 0) -> float:
    n = x * 374761393 + y * 668265263 + seed * 982451653
    n = (n ^ (n >> 13)) * 1274126177
    return ((n ^ (n >> 16)) & 0x7FFFFFFF) / 0x7FFFFFFF


def _fbm(x: float, y: float, octaves: int = 4, seed: int = 0) -> float:
    total = 0.0
    amp = 0.5
    freq = 1.0
    for i in range(octaves):
        sx = int(x * freq * 32) + seed * (i + 1)
        sy = int(y * freq * 32) + seed * (i + 7)
        total += _noise2d(sx, sy, seed + i) * amp
        amp *= 0.5
        freq *= 2.0
    return total


def _make_pixels(name: str, size: int) -> list[tuple[int, int, int, int]]:
    rng = random.Random(hash(name) & 0xFFFFFFFF)
    seed = rng.randint(0, 99999)
    pixels: list[tuple[int, int, int, int]] = []

    for y in range(size):
        for x in range(size):
            u = x / size
            v = y / size
            if name == "concrete_albedo":
                n = _fbm(u, v, 5, seed)
                g = _clamp(int(95 + n * 45))
                pixels.append((g, g - 4, g - 8, 255))
            elif name == "concrete_normal":
                nx = int((_fbm(u + 0.01, v, 3, seed) - _fbm(u - 0.01, v, 3, seed)) * 800 + 128)
                ny = int((_fbm(u, v + 0.01, 3, seed) - _fbm(u, v - 0.01, 3, seed)) * 800 + 128)
                pixels.append((_clamp(nx), _clamp(ny), 255, 255))
            elif name == "concrete_roughness":
                n = _fbm(u, v, 4, seed)
                g = _clamp(int(170 + n * 40))
                pixels.append((g, g, g, 255))
            elif name == "metal_albedo":
                n = _fbm(u * 2, v * 2, 3, seed)
                r = _clamp(int(120 + n * 30))
                g = _clamp(int(125 + n * 28))
                b = _clamp(int(135 + n * 25))
                pixels.append((r, g, b, 255))
            elif name == "metal_roughness":
                n = _fbm(u * 4, v * 4, 2, seed)
                g = _clamp(int(40 + n * 50))
                pixels.append((g, g, g, 255))
            elif name == "wood_albedo":
                grain = abs((v * 18 + _fbm(u, v, 2, seed) * 2) % 1.0 - 0.5)
                r = _clamp(int(110 + grain * 80))
                g = _clamp(int(70 + grain * 50))
                b = _clamp(int(40 + grain * 30))
                pixels.append((r, g, b, 255))
            elif name == "glass_albedo":
                n = _fbm(u, v, 2, seed) * 0.15
                pixels.append((_clamp(int(180 + n * 40)), _clamp(int(210 + n * 30)), _clamp(int(230 + n * 20)), 90))
            elif name == "plaster_albedo":
                n = _fbm(u, v, 4, seed)
                g = _clamp(int(210 + n * 25))
                pixels.append((g, g - 2, g - 6, 255))
            elif name == "asphalt_albedo":
                n = _fbm(u, v, 5, seed)
                speck = 1 if _noise2d(x, y, seed) > 0.97 else 0
                g = _clamp(int(35 + n * 25 + speck * 40))
                pixels.append((g, g, g + 2, 255))
            elif name == "emissive_strip":
                stripe = 1.0 if int(v * 12) % 2 == 0 else 0.15
                glow = stripe * (0.7 + 0.3 * _fbm(u, v, 2, seed))
                r = _clamp(int(40 + glow * 180))
                g = _clamp(int(200 + glow * 55))
                b = _clamp(int(255 * glow))
                pixels.append((r, g, b, 255))
            else:
                pixels.append((128, 128, 128, 255))
    return pixels


def _write_png_pure(path: Path, size: int, pixels: list[tuple[int, int, int, int]]) -> None:
    raw = bytearray()
    row_bytes = size * 4
    for y in range(size):
        raw.append(0)  # filter type None
        start = y * size
        for x in range(size):
            r, g, b, a = pixels[start + x]
            raw.extend((r, g, b, a))

    def chunk(tag: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(tag + data) & 0xFFFFFFFF
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", crc)

    ihdr = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    compressed = zlib.compress(bytes(raw), 9)
    png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", compressed) + chunk(b"IEND", b"")
    path.write_bytes(png)


def _write_png(path: Path, name: str, size: int = TEXTURE_SIZE) -> None:
    pixels = _make_pixels(name, size)
    if _HAS_PILLOW:
        img = Image.new("RGBA", (size, size))
        img.putdata(pixels)
        img.save(path, format="PNG")
    else:
        _write_png_pure(path, size, pixels)


def generate_textures(tex_dir: Path) -> dict[str, str]:
    tex_dir.mkdir(parents=True, exist_ok=True)
    out: dict[str, str] = {}
    for name in TEXTURE_NAMES:
        rel = f"textures/{name}.png"
        _write_png(tex_dir / f"{name}.png", name)
        out[name] = rel
    return out


