def build_materials(plan_materials: dict) -> dict:
    merged = {k: dict(v) if isinstance(v, dict) else v for k, v in BAKED_MATERIALS.items()}
    if isinstance(plan_materials, dict):
        for name, props in plan_materials.items():
            if isinstance(props, dict):
                entry = dict(merged.get(name, {}))
                entry.update(props)
                merged[name] = entry
            else:
                merged[name] = props
    return merged


